  // listesinde enkoder kodu yapısı [taban]-[çıkış fazı]-[kontrol çıkışı]-[besleme VDC][-konnektör] şeklinde;
  // listede aynı taban+kontrol çıkışı için konnektörsüz/C/CR/CS varyantları HER ZAMAN birbiriyle aynı
  // fiyatta (324/324 örnek, istisna yok) ve 1/5/24 VDC besleme varyantları da HER ZAMAN birbiriyle aynı
  // fiyatta (1303/1304 örnek, tek istisna: E40S6-1500-3-T, orada 24V/5V arası 7,8$ fark var ve o koda
  // dokunulmadı — zaten iki tarafı da ayrı ayrı doğru fiyatla eşleşiyor). Yani bu iki eksen (besleme
  // VDC, konnektör tipi) ürünün FİYATINI DEĞİŞTİRMİYOR, sadece siparişte hangi varyantın seçildiğini
  // belirtiyor — ilk eşleştirmede (23-10-2026) yalnızca listede BİREBİR yazan satırlar alınmış, aynı
  // taban/kontrol-çıkışı için listede sadece BİR besleme/konnektör kombinasyonu varsa diğerleri atlanmıştı.
  // Mert'in haklı çıkardığı uyarısı üzerine ("tüm encoderlerin kodları ve fiyatları fiyat listesinde
  // mevcut") bu simetri kullanılarak 1.561 ek kod eşleştirildi — hepsi, aynı taban+kontrol-çıkışı için
  // listede zaten var olan (sadece başka besleme/konnektör ile yazılmış) bir fiyattan türetildi, yeni/
  // tahmini bir fiyat UYDURULMADI. ENKODER kapsamı 4.752/8.644 (%55) → 6.313/8.644 (%73) oldu.
  // Kalan 2.331 kod (%27) için Autonics'in 2023 fiyat listesinde o taban+kontrol-çıkışı kombinasyonunun
  // HİÇBİR besleme/konnektör varyantıyla fiyatı yok (doğrudan .xlsx içinde metin aramasıyla doğrulandı,
  // ör. E58SS6 ailesinde "N" ve "V" kontrol çıkışının çoğu çözünürlükte hiç fiyatı yok, sadece "T" var) —
  // bu gerçek bir kaynak-listesi boşluğu, kod hatası değil.
